application.css:
* {
  box-sizing: border-box;
}

:root {
  color-scheme: light;
  --ink: #172033;
  --muted: #5d687b;
  --border: #d5dce7;
  --surface: #ffffff;
  --background: #f4f7fb;
  --accent: #2457c5;
  --accent-dark: #173d91;
  --danger: #a32d35;
  --focus: #f2a900;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--background);
  color: var(--ink);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

.app-shell {
  width: min(100% - 2rem, 760px);
  margin: 0 auto;
  padding: 3rem 0;
}

.app-header {
  margin-bottom: 2rem;
}

.eyebrow {
  margin: 0 0 .35rem;
  color: var(--accent-dark);
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: .5rem;
  font-size: clamp(2rem, 6vw, 3rem);
  line-height: 1.1;
}

h2 {
  margin-bottom: 1rem;
  font-size: 1.2rem;
}

.intro {
  max-width: 48ch;
  margin-bottom: 0;
  color: var(--muted);
}

.task-panel {
  margin-bottom: 1.25rem;
  padding: clamp(1.1rem, 4vw, 1.75rem);
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--surface);
  box-shadow: 0 5px 18px rgb(23 32 51 / 6%);
}

.input-row {
  display: flex;
  align-items: end;
  gap: .75rem;
}

.field-group {
  flex: 1;
}

label {
  display: block;
  margin-bottom: .4rem;
  font-size: .9rem;
  font-weight: 650;
}

input {
  width: 100%;
  min-height: 2.75rem;
  padding: .65rem .8rem;
  border: 1px solid #9ca8ba;
  border-radius: 7px;
  color: var(--ink);
  background: #fff;
  font: inherit;
}

button {
  min-height: 2.75rem;
  padding: .6rem 1rem;
  border: 0;
  border-radius: 7px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  font: inherit;
  font-weight: 700;
}

button:hover {
  background: var(--accent-dark);
}

button:focus-visible, input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.form-error {
  margin: .6rem 0 0;
  color: var(--danger);
  font-size: .9rem;
  font-weight: 650;
}

.list-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.count-summary {
  margin-bottom: 1rem;
  color: var(--muted);
  font-size: .9rem;
}

.count-summary span:first-child {
  color: var(--ink);
  font-weight: 750;
}

.task-list {
  display: grid;
  gap: .65rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.task-item {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .8rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fbfcfe;
}

.task-item.completed .task-text {
  color: var(--muted);
  text-decoration: line-through;
}

.task-text {
  flex: 1;
  overflow-wrap: anywhere;
}

.complete-control {
  width: 1.25rem;
  height: 1.25rem;
  min-height: 1.25rem;
  padding: 0;
  border: 2px solid #718096;
  border-radius: 4px;
  background: #fff;
  flex: 0 0 auto;
}

.complete-control[aria-pressed="true"] {
  border-color: var(--accent);
  background: var(--accent);
  box-shadow: inset 0 0 0 3px #fff;
}

.delete-control {
  min-height: 2.25rem;
  padding: .35rem .65rem;
  background: transparent;
  color: var(--danger);
}

.delete-control:hover {
  background: #fbecee;
  color: #7c2027;
}

.empty-message {
  margin: .5rem 0 0;
  color: var(--muted);
}

@media (max-width: 520px) {
  .app-shell {
    padding: 2rem 0;
  }

  .input-row {
    align-items: stretch;
    flex-direction: column;
  }

  .input-row button {
    width: 100%;
  }

  .list-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 0;
  }

  .task-item {
    align-items: flex-start;
  }
}

application.javascript:
const tasks = [];

const form = document.querySelector('#task-form');
const input = document.querySelector('[data-testid="task-input"]');
const taskList = document.querySelector('[data-testid="task-list"]');
const incompleteCount = document.querySelector('[data-testid="incomplete-count"]');
const countLabel = document.querySelector('#count-label');
const emptyMessage = document.querySelector('#empty-message');
const formError = document.querySelector('#form-error');

function createTask(text) {
  return { id: crypto.randomUUID ? crypto.randomUUID() : String(Date.now() + Math.random()), text, completed: false };
}

function updateCount() {
  const remaining = tasks.filter(task => !task.completed).length;
  incompleteCount.textContent = String(remaining);
  countLabel.textContent = remaining === 1 ? 'incomplete task' : 'incomplete tasks';
}

function renderTasks() {
  taskList.replaceChildren();
  emptyMessage.hidden = tasks.length > 0;

  tasks.forEach(task => {
    const item = document.createElement('li');
    item.className = 'task-item';
    item.dataset.testid = 'task';
    item.dataset.completed = String(task.completed);
    if (task.completed) item.classList.add('completed');

    const completeButton = document.createElement('button');
    completeButton.type = 'button';
    completeButton.className = 'complete-control';
    completeButton.dataset.testid = 'task-complete';
    completeButton.setAttribute('aria-label', task.completed ? `Mark ${task.text} as incomplete` : `Mark ${task.text} as complete`);
    completeButton.setAttribute('aria-pressed', String(task.completed));
    completeButton.addEventListener('click', () => toggleTask(task.id));

    const text = document.createElement('span');
    text.className = 'task-text';
    text.dataset.testid = 'task-text';
    text.textContent = task.text;

    const deleteButton = document.createElement('button');
    deleteButton.type = 'button';
    deleteButton.className = 'delete-control';
    deleteButton.dataset.testid = 'task-delete';
    deleteButton.textContent = 'Delete';
    deleteButton.setAttribute('aria-label', `Delete ${task.text}`);
    deleteButton.addEventListener('click', () => deleteTask(task.id));

    item.append(completeButton, text, deleteButton);
    taskList.append(item);
  });
  updateCount();
}

function showError(message) {
  formError.textContent = message;
  formError.hidden = false;
}

function clearError() {
  formError.textContent = '';
  formError.hidden = true;
}

function addTask(event) {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) {
    showError('Enter a task before adding it.');
    input.focus();
    return;
  }
  tasks.push(createTask(text));
  input.value = '';
  clearError();
  renderTasks();
  input.focus();
}

function toggleTask(id) {
  const task = tasks.find(item => item.id === id);
  if (!task) return;
  task.completed = !task.completed;
  renderTasks();
}

function deleteTask(id) {
  const index = tasks.findIndex(task => task.id === id);
  if (index === -1) return;
  tasks.splice(index, 1);
  renderTasks();
}

form.addEventListener('submit', addTask);
input.addEventListener('input', clearError);
renderTasks();
